// The literal after the first one (past whitespace and the comments skipped here); -1: none, or a
// comment opener to defer (the parse is then the unmarked one).
static int zw_second_literal(TSLexer *lexer, bool *line_break) {
  for (;;) {
    while (iswspace(lexer->lookahead)) { if (zw_line_terminator(lexer->lookahead)) *line_break = true; skip(lexer); }
    if (lexer->eof(lexer)) return -1;
    int l = zw_literal(lexer);
    if (l > -10) return l < 0 ? -1 : l;
    if (!zw_skip_comment(lexer, -10 - l, line_break)) return -1;
  }
}
// The start marker whose choice's conditions hold exactly as it stands for (-1: none). A condition
// holds where one of its paths begins the input; a second literal is read only when one is asked.
static int scan_starts(TSLexer *lexer, const bool *valid_symbols, int lit, uint64_t cand) {
  int lit2 = -3; bool line_break2 = false;
  for (unsigned i = 0; i < 16; i++) {
    const StartMarker *m = &START_MARKERS[i];
    if (!valid_symbols[m->symbol]) continue;
    uint32_t held = 0;
    for (unsigned j = 0; j < m->count; j++)
      for (unsigned k = 0; k < 20; k++) {
        const StartPath *p = &START_PATHS[k];
        if (p->cond != m->conds[j]) continue;
        if (p->lit >= 0 ? p->lit != lit : (lit >= 0 || !((cand >> p->tok) & 1))) continue;
        if (p->second >= 0) {
          if (lit2 == -3) lit2 = zw_second_literal(lexer, &line_break2);
          if (p->second != lit2 || (p->same_line && line_break2)) continue;
        }
        held |= (uint32_t)1 << j; break;
      }
    if (held && held == m->killed) return m->symbol;
  }
  return -1;
}
// A line-end token where its assertion holds (a line break or the end of the input, or a lookahead
// arm's token next); a same-line marker where no line break comes first. Either only when the next
// token may follow it (AFTER) and does not continue what precedes it (CONT). A start marker first.
// 1: returned; 0: declined; 2: declined before anything but whitespace was read, `/` next (regex).
static int scan_zero_width(TSLexer *lexer, const bool *valid_symbols) {
  lexer->mark_end(lexer);
  bool line_break = false, end;
  uint64_t cand; int lit;
  for (;;) {
    while (iswspace(lexer->lookahead)) { if (zw_line_terminator(lexer->lookahead)) line_break = true; skip(lexer); }
    if (valid_symbols[REGEX_LITERAL] && lexer->lookahead == '/') return 2;
    end = lexer->eof(lexer);
    cand = 0; lit = -1;
    if (!end) { cand = zw_token_candidates(lexer->lookahead); lit = zw_literal(lexer); }
    if (lit > -10) break;
    if (!zw_skip_comment(lexer, -10 - lit, &line_break)) return 0;
  }
  if (lit == -2) return 0;
  int32_t next = lexer->lookahead;   // the character after the literal (scan_starts may read on)
  // A start marker before every other token: where it is valid and its condition holds, the
  // alternative it excludes is the one a line-end or same-line token here would end or continue.
  if (!end) { int s = scan_starts(lexer, valid_symbols, lit, cand); if (s >= 0) { lexer->result_symbol = s; return 1; } }
  // Two passes: a keyword the token names itself first, then a keyword read as the word token.
  for (int pass = 0; pass < 2; pass++)
  for (unsigned i = 0; i < 12; i++) {
    const ZeroWidth *z = &ZERO_WIDTH[i];
    if (!valid_symbols[z->symbol]) continue;
    bool ahead = !end && (lit >= 0 ? z->ahead_lit[lit] : (cand & z->ahead_tok) != 0);
    bool holds = z->line_end ? ((z->line_break && (line_break || end)) || ahead) : (!line_break && !end);
    if (!holds) continue;
    bool after = end ? z->after_end : lit >= 0 ? (pass == 0 ? z->after_exact[lit] : z->after_lit[lit]) || (zw_lit_tokens(lit, next) & z->after_tok) != 0 : (cand & z->after_tok) != 0;
    bool cont = !end && (lit >= 0 ? z->cont_lit[lit] : (cand & z->cont_tok) != 0);
    if (after && !cont) { lexer->result_symbol = z->symbol; return 1; }
  }
  return 0;
}

bool tree_sitter_typescript_external_scanner_scan(void *payload, TSLexer *lexer,
                                                          const bool *valid_symbols) {
  (void)payload;

  // Error-recovery sentinel: tree-sitter marks EVERY external valid when it is
  // guessing. The regex slot (expression start) and a template-chars slot
  // (inside a template) are never both genuinely valid at once, so treat that
  // combination as recovery and decline — the regular lexer takes over.
  if (valid_symbols[TEMPLATE_CHARS] && valid_symbols[REGEX_LITERAL]) return false;

  // Template chars run first: whitespace INSIDE a template is literal text,
  // so it must NOT be skipped (unlike the regex path below).
  if (valid_symbols[TEMPLATE_CHARS]) {
    if (scan_template_chars(lexer)) return true;
  }

  // Zero-width tokens (a line-end alternative, a same-line marker, a start marker) where one is valid.
  if (valid_symbols[_SAME_LINE_1] || valid_symbols[_LINE_END_1] || valid_symbols[_SAME_LINE_2] || valid_symbols[_SAME_LINE_3] || valid_symbols[_SAME_LINE_4] || valid_symbols[_SAME_LINE_5] || valid_symbols[_SAME_LINE_6] || valid_symbols[_SAME_LINE_7] || valid_symbols[_SAME_LINE_8] || valid_symbols[_SAME_LINE_9] || valid_symbols[_SAME_LINE_10] || valid_symbols[_SAME_LINE_11] || valid_symbols[_STARTS_1] || valid_symbols[_STARTS_2] || valid_symbols[_STARTS_3] || valid_symbols[_STARTS_4] || valid_symbols[_STARTS_5] || valid_symbols[_STARTS_6] || valid_symbols[_STARTS_7] || valid_symbols[_STARTS_8] || valid_symbols[_STARTS_9] || valid_symbols[_STARTS_10] || valid_symbols[_STARTS_11] || valid_symbols[_STARTS_12] || valid_symbols[_STARTS_13] || valid_symbols[_STARTS_14] || valid_symbols[_STARTS_15] || valid_symbols[_STARTS_16]) {
    int zw = scan_zero_width(lexer, valid_symbols);
    if (zw == 1) return true;
    if (zw == 0) return false;
  }

  // Skip leading whitespace (the regular lexer normally does this, but the
  // external scanner runs first when any external symbol is valid).
  if (valid_symbols[REGEX_LITERAL]) {
    while (iswspace(lexer->lookahead)) skip(lexer);
    if (lexer->lookahead == '/') {
      if (scan_regex(lexer)) return true;
    }
  }

  return false;
}
